#include <bits/stdc++.h>
using namespace std;

const long long INF = 1000000000000000000LL;

int n, len, maxPow;
string k;
vector<long long> powers;
vector<vector<long long>> dp;

long long solve(int ind, int po) {
    if (ind == -1)
        return 0;
    if (po >= maxPow)
        return INF;

    long long &res = dp[ind][po];
    if (res != -1)
        return res;

    long long ans = INF + 1;
    long long num = 0;
    long long place = 1;

    for (int i = ind; i >= 0; --i) {
        int digit = k[i] - '0';

        if (digit != 0) {
            if (place >= n || digit * place > n - num)
                num = n;
            else
                num += digit * place;
        }

        bool leadingZero = (i < ind && k[i] == '0');

        if (!leadingZero) {
            if (num >= n)
                break;

            if (powers[po] > 0 && num <= LLONG_MAX / powers[po]) {
                long long value = num * powers[po];
                long long sub = solve(i - 1, po + 1);
                __int128 candidate = static_cast<__int128>(sub) + value;
                if (candidate < ans)
                    ans = static_cast<long long>(candidate);
            }
        }

        if (place < n) {
            if (place > n / 10)
                place = n;
            else
                place *= 10;
        }
    }

    return res = ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> k;
    len = static_cast<int>(k.size());

    powers.push_back(1);
    maxPow = 0;

    for (int i = 1; i < n && i <= len; ++i) {
        if (powers.back() > LLONG_MAX / n)
            break;
        powers.push_back(powers.back() * n);
        maxPow = i;
    }

    dp.assign(len, vector<long long>(maxPow + 1, -1));
    cout << solve(len - 1, 0);

    return 0;
}

