int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    string k;
    cin >> n >> k;

    const long long INF = 1000000000000000000LL;
    const int len = static_cast<int>(k.size());

    if (n <= 0) {
        cout << INF;
        return 0;
    }

    vector<long long> power(len, INF);
    if (len > 0) {
        power[0] = 1;
        for (int i = 1; i < len; ++i) {
            __int128 value = static_cast<__int128>(power[i - 1]) * n;
            power[i] = value >= INF ? INF : static_cast<long long>(value);
        }
    }

    vector<vector<long long>> dp(len + 1,
                                 vector<long long>(len + 1, INF));

    for (int po = 0; po <= len; ++po)
        dp[0][po] = 0;

    for (int end = 1; end <= len; ++end) {
        for (int po = 0; po < len; ++po) {
            long long num = 0;
            long long decimalPower = 1;

            for (int start = end - 1; start >= 0; --start) {
                int digit = k[start] - '0';
                __int128 value =
                    static_cast<__int128>(digit) * decimalPower + num;
                num = value >= n ? n : static_cast<long long>(value);

                if (num >= n)
                    break;

                if (!(end - start > 1 && k[start] == '0') &&
                    dp[start][po + 1] < INF) {
                    __int128 term =
                        static_cast<__int128>(num) * power[po];
                    __int128 candidate =
                        term + dp[start][po + 1];

                    if (candidate < dp[end][po])
                        dp[end][po] = static_cast<long long>(candidate);
                }

                __int128 nextPower =
                    static_cast<__int128>(decimalPower) * 10;
                decimalPower =
                    nextPower >= n ? n : static_cast<long long>(nextPower);
            }
        }
    }

    cout << dp[len][0];
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

int n;
int len;
long long power[60];
int maxPow = 0;
string k;
long long dp[65][65];

long long solve(int ind, int po) {
    if (ind == -1)
        return 0;
    if (po >= maxPow)
        return 1E18;

    if (dp[ind][po] != -1)
        return dp[ind][po];

    string s;
    long long ans = 1E18 + 1;

    for (int i = ind; i >= 0; i--) {
        s = k[i] + s;
        long long num;
        stringstream convert(s);
        convert >> num;

        if (s.length() > 1 && s[0] == '0')
            continue;

        if (num >= n || LONG_LONG_MAX / power[po] < num)
            break;

        ans = min(ans, solve(i - 1, po + 1) + num * power[po]);
    }

    return dp[ind][po] = ans;
}

int main() {
    cin >> n >> k;
    len = k.length();
    power[0] = 1;
    memset(dp, -1, sizeof dp);

    for (int i = 1; i < n; i++) {
        power[i] = power[i - 1] * n;
        if (power[i] < power[i - 1])
            break;
        maxPow = i;
    }

    cout << solve(len - 1, 0);
    return 0;
}

