int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    string k;
    cin >> n >> k;

    const long long INF = 1000000000000000000LL;
    int len = static_cast<int>(k.size());

    if (n <= 0) {
        cout << INF;
        return 0;
    }

    vector<long long> power(1, 1);
    for (int i = 1; i <= len; ++i) {
        if (n != 1 && power.back() > LLONG_MAX / n)
            break;
        power.push_back(power.back() * n);
    }

    vector<vector<long long>> dp(
        len, vector<long long>(power.size(), -1)
    );

    function<long long(int, int)> solve = [&](int ind, int po) -> long long {
        if (ind < 0)
            return 0;
        if (po >= static_cast<int>(power.size()))
            return INF;

        long long &res = dp[ind][po];
        if (res != -1)
            return res;

        res = INF;
        long long num = 0;
        long long decimalPower = 1;

        for (int i = ind; i >= 0; --i) {
            int digit = k[i] - '0';

            if (num < n) {
                if (digit != 0 &&
                    (decimalPower >= n ||
                     digit > (n - 1 - num) / decimalPower)) {
                    num = n;
                } else {
                    num += digit * decimalPower;
                }
            }

            if (i < ind && k[i] == '0') {
                if (decimalPower < n) {
                    if (decimalPower > (n - 1) / 10)
                        decimalPower = n;
                    else
                        decimalPower *= 10;
                }
                continue;
            }

            if (num >= n)
                break;

            long long previous = solve(i - 1, po + 1);
            __int128 value = static_cast<__int128>(num) * power[po] + previous;

            if (value < res)
                res = static_cast<long long>(value);

            if (decimalPower < n) {
                if (decimalPower > (n - 1) / 10)
                    decimalPower = n;
                else
                    decimalPower *= 10;
            }
        }

        return res;
    };

    cout << solve(len - 1, 0);
    return 0;
}

