    long long n;
    string k;
    cin >> n >> k;

    const long long INF = numeric_limits<long long>::max();
    int len = static_cast<int>(k.size());

    vector<long long> powers(1, 1);
    for (int i = 1; i <= len; ++i) {
        if (n <= 0 || powers.back() > INF / n)
            break;
        powers.push_back(powers.back() * n);
    }

    vector<vector<long long>> dp(len, vector<long long>(len + 1, -1));

    function<long long(int, int)> solve = [&](int ind, int po) -> long long {
        if (ind == -1)
            return 0;
        if (po >= static_cast<int>(powers.size()))
            return INF;

        long long &result = dp[ind][po];
        if (result != -1)
            return result;

        result = INF;
        __int128 num = 0;
        __int128 place = 1;

        for (int i = ind; i >= 0; --i) {
            num += static_cast<int>(k[i] - '0') * place;

            if (i < ind && k[i] == '0') {
                place = min(place * 10, static_cast<__int128>(n) + 1);
                continue;
            }

            if (num >= n)
                break;

            long long next = solve(i - 1, po + 1);
            __int128 total = num * powers[po];

            if (next != INF)
                total += next;
            else
                total = INF;

            if (total < result)
                result = static_cast<long long>(total);

            place = min(place * 10, static_cast<__int128>(n) + 1);
        }

        return result;
    };

    cout << solve(len - 1, 0);
    return 0;
}

